CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL, token_version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, text VARCHAR(1000) NOT NULL, a VARCHAR(500) NOT NULL,b VARCHAR(500) NOT NULL,c VARCHAR(500) NOT NULL,d VARCHAR(500) NOT NULL, answer INT NOT NULL);
